/* Generated by gen_packs.py from the original data files: pack "phoenix". */
MC.registerPack({"id":"phoenix","cards":[{"id":"34001a","name":"피닉스","en":"* Phoenix","type":"hero","enc":false,"unique":true,"hp":9,"atk":1,"thw":3,"def":2,"hs":5,"tr":["PSIONIC","X-MEN"],"traits":["사이오닉","엑스맨"],"text":"<i>사이오닉 결속</i> — <b>히어로 자원</b>: 피닉스 포스에서 힘 카운터를 1만큼 제거 → [wild] 자원을 생성함. (페이즈마다 1회 제한.)"},{"id":"34001b","name":"진 그레이","en":"* Jean Grey","type":"alter","enc":false,"unique":true,"hp":9,"rec":3,"hs":6,"tr":["MUTANT","PSIONIC"],"traits":["뮤턴트","사이오닉"],"text":"<b>사전 준비</b>: 당신의 피닉스 포스 업그레이드를 [[결박]] 면이 앞면으로 오도록 플레이 영역에 내려놓습니다. 그 카드에 힘 카운터를 4만큼 놓습니다.\n[star] <b>반응</b>: 당신이 기본 회복을 한 후, 피닉스 포스에 힘 카운터를 1만큼 놓습니다.","star":true},{"id":"34002a","name":"피닉스 포스","en":"Phoenix Force","type":"upgrade","enc":false,"unique":false,"res":"B","cls":"Hero","tr":["RESTRAINED"],"permanent":1,"traits":["결박"],"text":"영속.\n당신은 [[결박]] 특성을 얻습니다.\n<b>강제 반응</b>: 이 카드에서 마지막 힘 카운터가 제거된 후, 이 카드를 뒤집습니다."},{"id":"34002b","name":"피닉스 포스","en":"Phoenix Force","type":"upgrade","enc":false,"unique":false,"res":"R","cls":"Hero","tr":["UNLEASHED"],"permanent":1,"traits":["해방"],"text":"영속.\n당신은 [[해방]] 특성을 얻습니다.\n피닉스는 저지 -2와 공격 +2를 받습니다.\n<b>강제 반응</b>: 이 카드에 힘 카운터가 놓인 후, 이 카드에 힘 카운터가 4 이상 있다면, 이 카드를 뒤집습니다."},{"id":"34003","name":"사이클롭스","en":"* Cyclops","type":"ally","enc":false,"sub":"스콧 서머스","unique":true,"hp":3,"atk":2,"atkStar":true,"thw":2,"thwStar":true,"cost":3,"res":"G","cls":"Hero","tr":["X-MEN"],"traits":["엑스맨"],"text":"<b>반응</b>: 사이클롭스가 플레이 영역에 들어온 후, 피닉스 포스에 힘 카운터를 2만큼 놓습니다.\n<b>반응</b>: 사이클롭스가 플레이 영역을 떠날 때, 피닉스 포스에서 힘 카운터를 2만큼 제거합니다."},{"id":"34004","name":"화이트 핫 룸","en":"* White Hot Room","type":"support","enc":false,"unique":true,"cost":2,"res":"B","cls":"Hero","tr":["LOCATION","PHOENIX"],"traits":["장소","피닉스"],"text":"<b>일상 행동</b>: 화이트 핫 룸을 소진 → 다음 중 하나를 선택.\n• 피닉스 포스에 힘 카운터를 1만큼 놓습니다.\n• 진 그레이가 입은 피해 2점을 치료합니다."},{"id":"34005","name":"피닉스 슈트","en":"* Phoenix Suit","type":"upgrade","enc":false,"unique":true,"cost":2,"res":"R","cls":"Hero","tr":["ITEM"],"traits":["도구"],"text":"피닉스는 [[공중]] 특성을 얻습니다.\n당신이 [[결박]] 특성을 가지고 있는 동안, 당신은 의연을 얻습니다.\n당신이 [[해방]] 특성을 가지고 있는 동안, 당신은 반격 1을 얻습니다."},{"id":"34006","name":"잿더미에서 일어나다","en":"Rise from the Ashes","type":"upgrade","enc":false,"unique":false,"cost":3,"res":"Y","cls":"Hero","tr":["PHOENIX"],"traits":["피닉스"],"text":"<b>난입</b>: 당신이 격파되려 할 때, 이 카드를 게임에서 제거 → 대신 당신의 아이덴티티를 준비하고 인쇄된 생명력 수치로 회복시킴. 피닉스 포스에서 모든 힘 카운터를 제거함."},{"id":"34007","name":"염동력 방패","en":"Telekinetic Shield","type":"upgrade","enc":false,"unique":false,"cost":2,"res":"R","cls":"Hero","tr":["PSIONIC"],"traits":["사이오닉"],"text":"아군 캐릭터에게 장착합니다.\n<b>강제 난입</b>: 장착된 캐릭터가 적의 공격으로 피해를 입으려 할 때, 대신 그 피해를 이 카드에 놓습니다. 그러고 나서 이 카드에 피해가 5 이상 있다면, 염동력 방패를 버립니다."},{"id":"34008","name":"정신 마비","en":"Mental Paralysis","type":"upgrade","enc":false,"unique":false,"cost":2,"res":"B","cls":"Hero","tr":["PSIONIC"],"traits":["사이오닉"],"text":"히어로 형태 전용. [[간부]]가 아닌 하수인에게 장착합니다.\n장착된 하수인은 활성화할 수 없습니다.\n<b>강제 반응</b>: 당신이 일상 형태로 뒤집은 후, 이 카드를 버립니다."},{"id":"34009","name":"정신 조종","en":"Mind Control","type":"upgrade","enc":false,"unique":false,"cost":4,"res":"B","cls":"Hero","tr":["CONDITION","PSIONIC"],"traits":["상태","사이오닉"],"text":"[[간부]]가 아닌 하수인 하나에게 장착합니다.\n장착된 하수인의 조종권을 가져오고, 그 하수인을 문구 상자가 백지인 [[조종됨]] 동료로 봅니다. 그 동료의 저지는 인쇄된 음모 수치와 같으며, 저지하거나 공격한 후 부수적 피해 1점을 입습니다."},{"id":"34010","name":"염동력 공격","en":"Telekinetic Attack","type":"event","enc":false,"unique":false,"cost":3,"res":"R","cls":"Hero","tr":["ATTACK","PSIONIC"],"traits":["공격","사이오닉"],"text":"<b>히어로 행동</b><i>(공격)</i>: 적 하나에게 피해 7점을 입힙니다. 당신이 [[해방]] 특성을 가지고 있다면, 이 공격은 피해 2점을 추가로 입히고 압살을 얻습니다."},{"id":"34011","name":"사이킥 블래스트","en":"Psychic Blast","type":"event","enc":false,"unique":false,"cost":2,"res":"Y","cls":"Hero","tr":["PSIONIC"],"traits":["사이오닉"],"text":"<b>히어로 행동</b>: 빌런에게 피해 4점을 입힙니다. 당신이 [[해방]] 특성을 가지고 있다면, 당신과 교전 중인 각 하수인에게 피해 4점을 입힙니다."},{"id":"34012","name":"텔레파시 속임수","en":"Telepathic Trickery","type":"event","enc":false,"unique":false,"cost":2,"res":"B","cls":"Hero","tr":["PSIONIC","THWART"],"traits":["사이오닉","저지"],"text":"<b>히어로 행동</b><i>(저지)</i>: 음모 하나에서 위협을 4만큼 제거합니다. 당신이 [[해방]] 특성을 가지고 있다면, 적 하나를 기절시키고 혼란에 빠뜨립니다."},{"id":"34013","name":"피닉스 불새","en":"Phoenix Firebird","type":"event","enc":false,"unique":false,"cost":1,"res":"Y","cls":"Hero","tr":["PHOENIX"],"traits":["피닉스"],"text":"<b>히어로 행동</b>: 다음 중 하나를 선택합니다.\n• 피닉스 포스에서 힘 카운터를 1만큼 제거 → 피닉스를 준비함.\n• 피닉스 포스에 힘 카운터를 2만큼 놓습니다."},{"id":"34014","name":"밴시","en":"* Banshee","type":"ally","enc":false,"sub":"숀 캐시디","unique":true,"hp":3,"atk":2,"atkStar":true,"thw":2,"thwStar":true,"cost":4,"res":"Y","cls":"Justice","tr":["AERIAL","X-MEN"],"traits":["공중","엑스맨"],"text":"[star] <b>반응</b>: 밴시가 저지한 후, 하수인 하나를 혼란에 빠뜨립니다.","star":true},{"id":"34015","name":"마블 걸","en":"* Marvel Girl","type":"ally","enc":false,"sub":"레이첼 서머스","unique":true,"hp":3,"atk":1,"atkStar":true,"thw":2,"thwStar":true,"cost":3,"res":"B","cls":"Justice","tr":["PSIONIC","X-MEN"],"traits":["사이오닉","엑스맨"],"text":"[star] <b>난입</b>: 마블 걸이 하수인을 공격할 때, 주요 음모에서 위협을 X만큼 제거합니다. X는 그 하수인에 인쇄된 음모 수치입니다.","star":true},{"id":"34016","name":"임무 훈련","en":"Mission Training","type":"upgrade","enc":false,"unique":false,"cost":1,"res":"B","cls":"Justice","tr":["TRAINING"],"traits":["훈련"],"text":"[[엑스맨]] 동료에게 장착합니다. 동료마다 [[훈련]] 업그레이드 최대 1장.\n장착된 동료는 저지 +1과 생명력 +2를 받습니다."},{"id":"34017","name":"정신 조작","en":"Psychic Manipulation","type":"event","enc":false,"unique":false,"cost":3,"res":"Y","cls":"Justice","tr":["PSIONIC","THWART"],"traits":["사이오닉","저지"],"text":"당신의 아이덴티티가 [[사이오닉]] 특성을 가지고 있을 때만 플레이할 수 있습니다.\n<b>난입</b><i>(저지)</i>: 빌런이 암약할 때, 이 활성화는 위협을 놓는 대신 제거합니다."},{"id":"34018","name":"뮤턴트 평화유지군","en":"Mutant Peacekeepers","type":"event","enc":false,"unique":false,"cost":1,"res":"R","cls":"Justice","tr":["THWART"],"traits":["저지"],"text":"당신의 아이덴티티에게 [[엑스맨]] 특성이 있을 때만 플레이합니다.\n<b>히어로 행동</b><i>(저지)</i>: 당신의 히어로와 원하는 수의 [[엑스맨]] 동료를 소진 → 플레이 영역에 있는 음모들에서 위협을 총 X만큼 나누어 제거함. X는 그 캐릭터들의 저지 수치 합계임."},{"id":"34019","name":"재빠른 응징","en":"Swift Retribution","type":"event","enc":false,"unique":false,"cost":1,"res":"B","cls":"Justice","tr":["ATTACK"],"traits":["공격"],"text":"<b>히어로 행동</b><i>(공격)</i>: 빌런이 암약합니다. 빌런에게 피해 4점을 입힙니다.","link":"15014"},{"id":"34020","name":"정의를 향한 열정","en":"Passion for Justice","type":"resource","enc":false,"unique":false,"res":"G","cls":"Justice","tr":[],"maxDeck":2,"traits":[],"text":"덱마다 최대 2장.\n<b>난입</b>: 당신이 [[저지]] 이벤트를 플레이하기 위해 이 카드를 소모할 때, 그 이벤트는 위협을 1만큼 추가로 제거합니다."},{"id":"34021","name":"스톰","en":"* Storm","type":"ally","enc":false,"sub":"오로로 먼로","unique":true,"hp":3,"atk":2,"atkStar":true,"thw":2,"thwStar":true,"cost":5,"res":"Y","cls":"Basic","tr":["AERIAL","X-MEN"],"traits":["공중","엑스맨"],"text":"당신의 아이덴티티가 [[뮤턴트]] 또는 [[엑스맨]] 특성을 가지고 있다면, 스톰을 플레이하는 비용이 1 감소합니다.\n[star] <b>난입</b>: 스톰이 음모를 저지할 때, 그 음모에서 다른 음모로 위협을 2만큼 옮깁니다.","star":true},{"id":"34022","name":"세레브로","en":"* Cerebro","type":"support","enc":false,"unique":true,"cost":1,"res":"B","cls":"Basic","tr":["LOCATION","X-MEN"],"traits":["장소","엑스맨"],"text":"당신의 아이덴티티가 [[뮤턴트]] 특성을 가지고 있을 때만 플레이합니다.\n<b>일상 행동</b>: 세레브로를 소진 → 당신의 덱 맨 위 카드 5장에서 [[엑스맨]] 동료 1장을 찾아(당신이 [[사이오닉]] 캐릭터를 조종하고 있다면 대신 덱 전체에서 찾음) 그 동료를 당신의 손에 더함. <i>(덱을 섞습니다.)</i>"},{"id":"34023","name":"정신 교감","en":"Psychic Rapport","type":"event","enc":false,"unique":false,"cost":2,"res":"Y","cls":"Basic","tr":[],"teamUp":["Cyclops","Phoenix"],"maxDeck":1,"traits":[],"text":"협력 (사이클롭스와 피닉스). 덱마다 최대 1장.\n<b>히어로 행동</b>: 사이클롭스와 피닉스를 준비합니다. 당신의 버린 더미에서 사이클롭스 카드 1장을 당신의 손으로 되돌리거나, 피닉스 포스에 파워 카운터를 2만큼 놓는 것 중 하나를 선택합니다.","link":"33023"},{"id":"34024","name":"휴식 시간","en":"Down Time","type":"upgrade","enc":false,"unique":false,"cost":1,"res":"R","cls":"Basic","tr":["CONDITION"],"maxPer":1,"traits":["상태"],"text":"이 카드를 플레이하면, 조종할 플레이어를 정합니다. 플레이어마다 최대 1장.\n당신의 일상은 회복 +2를 받습니다.","link":"05033"},{"id":"34025","name":"에너지","en":"Energy","type":"resource","enc":false,"unique":false,"res":"YY","cls":"Basic","tr":[],"maxDeck":1,"traits":[],"text":"덱마다 최대 1장.","link":"01088"},{"id":"34026","name":"천재","en":"Genius","type":"resource","enc":false,"unique":false,"res":"BB","cls":"Basic","tr":[],"maxDeck":1,"traits":[],"text":"덱마다 최대 1장.","link":"01089"},{"id":"34027","name":"힘","en":"Strength","type":"resource","enc":false,"unique":false,"res":"RR","cls":"Basic","tr":[],"maxDeck":1,"traits":[],"text":"덱마다 최대 1장.","link":"01090"},{"id":"34028","name":"불타는 갈망","en":"Burning Hunger","type":"obligation","enc":true,"set":"Phoenix","unique":false,"boost":2,"tr":[],"traits":[],"text":"<b><i>진 그레이 플레이어에게 이 카드를 줍니다.</i></b>\n<b>공개될 때</b>: 당신이 [[해방]] 특성을 가지고 있다면, 조우 덱, 버린 조우 더미, 따로 놓아둔 영역에서 다크 피닉스를 찾아 공개합니다. 그러고 나서, 불타는 갈망을 게임에서 제거합니다. 당신이 [[결박]] 특성을 가지고 있다면, 피닉스 포스에서 힘 카운터를 1만큼 제거하고 이 카드는 쇄도를 얻습니다. 이 카드를 버립니다."},{"id":"34029","name":"다크 피닉스","en":"* Dark Phoenix","type":"minion","enc":true,"set":"Phoenix Nemesis","unique":true,"hp":12,"atk":2,"sch":2,"boost":3,"tr":["COSMIC ENTITY","ELITE"],"toughness":1,"villainous":1,"steady":1,"nemesis":true,"traits":["우주적 존재","간부"],"text":"의연. 강인. 악당.\n[star] 다크 피닉스가 암약할 때, 가능하다면 그 위협을 세상을 집어삼켜라에 놓습니다.\n<b>공개될 때</b>: 조우 덱, 버린 조우 더미, 따로 놓아둔 영역에서 세상을 집어삼켜라를 찾아 공개합니다.","star":true},{"id":"34030","name":"세상을 집어삼켜라","en":"Consume the World","type":"side","enc":true,"set":"Phoenix Nemesis","unique":false,"boost":3,"start":6,"tr":[],"amplify":1,"permanent":1,"traits":[],"text":"영속.\n이 카드에 위협이 없는 동안, 이 음모는 [amplify] 아이콘을 잃습니다.\n<b>강제 반응</b>: 이 카드에 위협이 놓인 후, 이 카드에 위협이 12 이상 있다면, 플레이어들은 게임에서 패배합니다."},{"id":"34031","name":"불타는 분노","en":"Fiery Rage","type":"treachery","enc":true,"set":"Phoenix Nemesis","unique":false,"boost":2,"tr":[],"peril":1,"traits":[],"text":"고립. <i>(당신이 이 카드를 해결하는 동안, 다른 플레이어들은 당신을 도울 수 없습니다.)</i>\n<b>공개될 때</b>: 다크 피닉스가 플레이 영역에 있다면, 다크 피닉스는 당신을 상대로 활성화합니다. 다크 피닉스가 플레이 영역에 없다면, 세상을 집어삼켜라에 위협을 1만큼 놓고 이 카드는 쇄도를 얻습니다."},{"id":"34032","name":"정신 공격","en":"Psychic Assault","type":"event","enc":false,"unique":false,"cost":2,"res":"Y","cls":"Aggression","tr":["ATTACK","PSIONIC"],"traits":["공격","사이오닉"],"text":"당신의 아이덴티티가 [[사이오닉]] 특성을 가지고 있을 때만 플레이할 수 있습니다.\n<b>히어로 행동</b><i>(공격)</i>: 적 하나에게 피해 3점을 입힙니다. 그 적을 혼란에 빠뜨립니다."},{"id":"34033","name":"정신 교란","en":"Psychic Misdirection","type":"event","enc":false,"unique":false,"cost":2,"res":"Y","cls":"Protection","tr":["DEFENSE","PSIONIC"],"traits":["방어","사이오닉"],"text":"당신의 아이덴티티가 [[사이오닉]] 특성을 가지고 있을 때만 플레이할 수 있습니다.\n<b>히어로 난입</b><i>(방어)</i>: 적이 당신을 공격할 때, 다른 적 하나를 선택 → 그 공격의 피해를 당신 대신 선택한 적이 입음."},{"id":"34034","name":"사이킥 부스트","en":"Psychic Kicker","type":"event","enc":false,"unique":false,"cost":0,"res":"Y","cls":"Leadership","tr":["PSIONIC"],"traits":["사이오닉"],"text":"당신의 아이덴티티가 [[사이오닉]] 특성을 가지고 있을 때만 플레이할 수 있습니다.\n<b>히어로 행동</b>: 동료 하나를 준비합니다. 그 동료는 이번 페이즈에 하는 다음 기본 저지 또는 기본 공격 행동에 저지 +2와 공격 +2를 받습니다."},{"id":"34035","name":"영혼의 자매","en":"Soul Sisters","type":"event","enc":false,"unique":false,"cost":1,"res":"Y","cls":"Basic","tr":[],"teamUp":["Phoenix","Storm"],"maxDeck":1,"traits":[],"text":"협력(피닉스와 스톰). 덱마다 최대 1장.\n<b>히어로 행동</b>: 피닉스와 스톰을 준비합니다. 둘에게서 각각 피해 2점을 치료합니다."}]});
